int logfmt_parse_multi(const char *in, char **keys, size_t k_sz, size_t *n_keys,
                       char **vals, size_t v_sz, size_t *n_vals, size_t max_count) {
    if (in == NULL || keys == NULL || vals == NULL || n_keys == NULL || n_vals == NULL) {
        return -1;
    }
    if (k_sz == 0 || v_sz == 0 || max_count == 0) {
        return -1;
    }

    size_t count = 0;
    const char *p = in;

    while (*p != '\0' && count < max_count) {
        /* skip leading spaces */
        while (*p == ' ' || *p == '\t') p++;
        if (*p == '\0') break;

        const char *eq = strchr(p, '=');
        if (eq == NULL) return -1;

        size_t klen = (size_t)(eq - p);
        if (klen >= k_sz) return -1;
        memcpy(keys[count], p, klen);
        keys[count][klen] = '\0';

        const char *vstart = eq + 1;
        const char *vend = strchr(vstart, ' ');
        if (vend) {
            while (*vend == ' ' || *vend == '\t') {
                /* consume space as separator, but we need to stop at next token boundary */
                break;
            }
            vend = vstart;
            while (*vend != '\0' && *vend != ' ' && *vend != '\t') vend++;
        } else {
            vend = vstart + strlen(vstart);
        }
        size_t vlen = (size_t)(vend - vstart);
        if (vlen >= v_sz) return -1;
        memcpy(vals[count], vstart, vlen);
        vals[count][vlen] = '\0';

        count++;
        p = vend;
    }

    *n_keys = count;
    *n_vals = count;
    return 0;
}

